const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=(v,n=1)=>Number.isFinite(v)?v.toLocaleString('tr-TR',{maximumFractionDigits:n,minimumFractionDigits:n}):'—';
const pct=(v,n=1)=>Number.isFinite(v)?'%'+number(v*100,n):'—';
const date=(v,full=false)=>new Date(v).toLocaleDateString('tr-TR',full?{day:'numeric',month:'long',year:'numeric',timeZone:'Europe/Istanbul'}:{day:'2-digit',month:'short',timeZone:'Europe/Istanbul'});
const short=n=>String(n).replace('Manchester United','Man United').replace('AFC Bournemouth','Bournemouth').replace('Hotspur','').replace('United','Utd').replace('Nottingham Forest','Nottm Forest');
const titles={overview:'Genel bakış',form:'Son 10 maç',network:'Rakip ağı',similar:'Benzer maçlar',data:'Veri kütüphanesi',method:'Model laboratuvarı',players:'Oyuncu ağı',simulation:'Maç simülasyonu',h2h:'H2H karşılaşmaları',markets:'Seriler ve pazarlar','market-network':'Pazar ağı'};
const translation={BallPossesion:'Topa sahip olma (%)',expected_goals:'Beklenen gol (xG)',total_shots:'Toplam şut',ShotsOnTarget:'İsabetli şut',touches_opp_box:'Rakip ceza sahasında dokunuş',big_chance:'Büyük fırsat',big_chance_missed_title:'Kaçan büyük fırsat',accurate_passes:'İsabetli pas',yellow_cards:'Sarı kart',corners:'Korner',ShotsOffTarget:'İsabetsiz şut',blocked_shots:'Engellenen şut',shots_woodwork:'Direkten dönen şut',shots_inside_box:'Ceza sahası içi şut',shots_outside_box:'Ceza sahası dışı şut',expected_goals_open_play:'Açık oyunda xG',expected_goals_set_play:'Duran topta xG',expected_goals_non_penalty:'Penaltı hariç xG',expected_goals_on_target:'İsabetli şut xG (xGOT)',passes:'Toplam pas',own_half_passes:'Kendi yarı sahasında pas',opposition_half_passes:'Rakip yarı sahasında pas',long_balls_accurate:'İsabetli uzun top',accurate_crosses:'İsabetli orta',player_throws:'Taç atışı',Offsides:'Ofsayt','matchstats.headers.tackles':'Top kapma',interceptions:'Pas arası',shot_blocks:'Şut bloklama',clearances:'Uzaklaştırma',keeper_saves:'Kaleci kurtarışı',duel_won:'Kazanılan ikili mücadele',ground_duels_won:'Kazanılan yer mücadelesi',aerials_won:'Kazanılan hava mücadelesi',dribbles_succeeded:'Başarılı çalım',red_cards:'Kırmızı kart',fouls:'Faul',physical_metrics_distance_covered:'Kat edilen mesafe (m)',physical_metrics_running:'Koşu mesafesi (m)',physical_metrics_sprinting:'Sprint mesafesi (m)',physical_metrics_number_of_sprints:'Sprint sayısı',physical_metrics_walking:'Yürüme mesafesi (m)'};
const groupNames={'Top stats':'Öne çıkanlar','Shots':'Şutlar','Expected goals (xG)':'Beklenen gol','Passes':'Paslar','Defence':'Savunma','Defense':'Savunma','Duels':'İkili mücadeleler','Discipline':'Disiplin','Physical metrics':'Fiziksel veriler','Physical performance':'Fiziksel veriler','Physical performance':'Fiziksel veriler','Physical performance':'Fiziksel veriler','Physical performance':'Fiziksel veriler'};
let bundle,result,active='overview',selectedTeam,statPeriod='All',search='',options={depth:2,halfLife:60,neighbors:12,similarityWeight:.25,formCount:10,playerLayer:true,playerScenarios:{},playerGraphMode:'market-graph',h2hLayer:true,h2hWeight:.35,h2hHalfLife:365},testRun=null;
function badge(team){return `<img class="team-badge" src="https://images.fotmob.com/image_resources/logo/teamlogo/${Number(team.id)}.png" alt="${esc(team.name)} arması" width="50" height="58" onerror="this.style.visibility='hidden'">`;}
function formPills(rows){return rows.slice().reverse().map(r=>`<span class="form-pill ${r.result}" title="${esc(r.opponent.name)}: ${r.gf}–${r.ga}">${({W:'G',D:'B',L:'M'})[r.result]}</span>`).join('');}
function go(view){if(view!=='market-network')stopMarketNetwork();if(view!=='players')stopPlayerExplorer();if(view!=='simulation')stopSimulation();if(!bundle||!result){active=view;location.hash=view;return;}active=view;$$('.view').forEach(v=>v.classList.toggle('hidden',v.id!=='view-'+view));$$('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);if(b.hasAttribute('role'))b.setAttribute('aria-selected',b.dataset.view===view?'true':'false');});$('#view-title').textContent=titles[view];location.hash=view;if(view==='simulation')renderSimulation($('#view-simulation'),{bundle,result,options,esc,number,pct,download,recalculate:()=>{testRun=null;recalc();}});if(view==='h2h')renderH2H($('#view-h2h'),{bundle,result,options,esc,number,pct,date,download,recalculate:()=>{testRun=null;recalc();}});if(view==='market-network')renderMarketNetwork($('#view-market-network'),{bundle,result,esc,number,pct,date});if(view==='network')network();if(view==='players')renderPlayers($('#view-players'),{bundle,result,options,esc,number,pct,date,download,openMatch:matchDetail,recalculate:()=>{testRun=null;recalc();}});}
function toast(msg){const div=document.createElement('div');div.className='toast';div.textContent=msg;document.body.append(div);setTimeout(()=>div.remove(),3500);}
function download(name,data,type='application/json'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
let recalcId=0;async function recalc(){const request=++recalcId;stopSimulation(true);$('#form-coverage').textContent='GBDT eğitiliyor; zaman sıralı doğrulama hazırlanıyor…';try{await warmTraining(bundle,options);}catch(e){$('#loading').textContent='Model eğitimi başarısız: '+e.message;$('#loading').classList.remove('hidden');return false;}if(request!==recalcId)return;await new Promise(resolve=>setTimeout(resolve,0));if(request!==recalcId)return;titles.form='Son '+options.formCount+' maç';$('#form-count').value=String(options.formCount);$('#prediction-model').value=options.playerGraphMode??'auto';document.querySelectorAll('.nav[data-view="form"]').forEach(b=>b.innerHTML='<span>≋</span> Son '+options.formCount+' maç');$('#form-coverage').textContent='';result=analyze(bundle,options);selectedTeam??=String(bundle.target.home.id);$('#player-layer-toggle').checked=options.playerLayer!==false;$('#h2h-layer-toggle').checked=options.h2hLayer!==false;$('#h2h-impact').textContent=result.h2hAnalysis?'H2H etkisi: '+number((result.h2hAnalysis.factors.home-1)*100,2)+'% / '+number((result.h2hAnalysis.factors.away-1)*100,2)+'%':'';const pa=result.playerAnalysis;$('#player-impact').textContent=result.training?.gbdt?.active?'İlk 11 etkisi GBDT içinde öğrenilir':pa?'Oyuncu etkisi: '+number(((pa.adjustments.home.factor??1)-1)*100,2)+'% / '+number(((pa.adjustments.away.factor??1)-1)*100,2)+'% gol yoğunluğu':'';$('#form-coverage').textContent=result.homeForm.length+'/'+options.formCount+' ve '+result.awayForm.length+'/'+options.formCount+' resmi maç mevcut';render();}
function heading(){const t=bundle.target;$('#match-header').innerHTML=`<div class="match-meta"><span class="league-icon">${Number(t.leagueId)===47?'PL':'●'}</span><span>${esc(t.leagueName)}</span><span>·</span><span>${date(t.date,true)}</span><span>·</span><span>Maç öncesi analiz</span></div><div class="match-row"><div class="team-title">${badge(t.home)}<div><h2>${esc(t.home.name)}</h2><div class="form-dots">${formPills(result.homeForm)}</div></div></div><div class="match-center"><div class="vs">VS</div><div class="match-time">${new Date(t.date).toLocaleTimeString('tr-TR',{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Istanbul'})} / İstanbul</div><div class="cutoff-tag">${t.finished?'GEÇMİŞE DÖNÜK TAHMİN':t.started?'MAÇ ÖNCESİ MODEL':'HENÜZ OYNANMADI'}</div></div><div class="team-title away">${badge(t.away)}<div><h2>${esc(t.away.name)}</h2><div class="form-dots">${formPills(result.awayForm)}</div></div></div></div><div class="match-sub"><span>${t.finished?'Veri sınırı: başlama saatinden önce tamamlanan maçlar':'Veri sınırı: analiz anına kadar tamamlanan maçlar'} · Son ${result.homeForm.length} / ${result.awayForm.length} resmi karşılaşma</span><a href="${esc(t.url)}" target="_blank" rel="noreferrer">FotMob’da görüntüle ↗</a></div>`;}
const avgRows=[['gf','Atılan gol'],['ga','Yenilen gol'],['xg','Beklenen gol (xG)'],['xga','Rakip xG'],['shots','Toplam şut'],['shotsOnTarget','İsabetli şut'],['possession','Topa sahip olma %'],['corners','Korner']];
function comparison(){const {home,away}=result.profiles;return `<div class="legend-title"><span>${esc(short(bundle.target.home.name))}</span><span>Maç başı ortalama</span><span>${esc(short(bundle.target.away.name))}</span></div>${avgRows.map(([key,label])=>{const h=home[key],a=away[key],max=Math.max(h||0,a||0,.01);return `<div class="comparison-row"><span>${number(h)}</span><div class="bar-track home"><div class="fill" style="width:${(h||0)/max*100}%"></div></div><span class="metric-label">${label}</span><div class="bar-track away"><div class="fill" style="width:${(a||0)/max*100}%"></div></div><span>${number(a)}</span></div>`;}).join('')}`;}
function overview(){const p=result.prediction,t=bundle.target;if(!p){$('#view-overview').innerHTML='<div class="empty">Tahmin için her iki takımın en az 3 geçmiş maçına ihtiyaç var.</div>';return;}const top=p.topScores[0];$('#view-overview').innerHTML=`<div class="grid main-grid"><section class="card"><div class="card-title"><h2>Skor projeksiyonu</h2><span class="tag">MODEL v${MODEL_VERSION}</span></div><div class="big-score"><strong>${top.home}<span>:</span>${top.away}</strong><div class="score-caption"><b>${pct(top.probability)}</b>en olası tek skor<br><span class="muted">${esc(short(t.home.name))} – ${esc(short(t.away.name))}</span></div></div><div class="probability-bar" aria-label="1X2 dağılımı"><div style="width:${p.outcomes.home*100}%"></div><div style="width:${p.outcomes.draw*100}%"></div><div style="width:${p.outcomes.away*100}%"></div></div><div class="probability-labels"><div>EV SAHİBİ / 1<b>${pct(p.outcomes.home)}</b></div><div>BERABERLİK / X<b>${pct(p.outcomes.draw)}</b></div><div>DEPLASMAN / 2<b>${pct(p.outcomes.away)}</b></div></div><div class="prediction-foot"><span>Beklenen gol <b>${number(p.homeXg,2)} – ${number(p.awayXg,2)}</b></span><span>${result.training?.marketNetwork?.active?'Pazar ağıyla geçmiş sonuçlardan öğrenildi':result.training?.gbdt?.active?'GBDT · ilk 11 + oyuncu ağı':result.training?.playerGraph?.active?'Oyuncu ağıyla öğrenildi':result.training?.accepted?'Geçmiş sonuçlarla öğrenildi':result.neighbors.length+' benzer maç katkısı'}</span></div></section><section class="card"><div class="card-title"><h2>Maçların arkasındaki ağ</h2><button class="text-button" data-view="network">Ağı keşfet ↗</button></div><div class="network-preview">${graphSvg(true)}</div><div class="network-legend"><span><i></i>${esc(short(t.home.name))}</span><span><i></i>${esc(short(t.away.name))}</span><span><i></i>Bağlı rakipler</span></div></section></div><div class="metric-strip"><div><b>${bundle.matches.length}<small>maç</small></b><span>Toplanan geçmiş maç</span></div><div><b>${result.graph.nodes.length}<small>takım</small></b><span>Seçili rakip ağında</span></div><div><b>${bundle.inventory.length}<small>metrik</small></b><span>Bulunan istatistik türü</span></div><div><b>${result.neighbors.length}<small>eşleşme</small></b><span>Benzer geçmiş profiller</span></div></div><div class="grid two"><section class="card"><div class="card-title"><h2>Son ${options.formCount} maçın anlattıkları</h2><button class="text-button" data-view="form">Tüm veriler ↗</button></div>${comparison()}</section><section class="card"><div class="card-title"><h2>Alternatif senaryolar</h2><span class="kicker">SKOR OLASILIKLARI</span></div><div class="score-list">${p.topScores.slice(0,4).map(s=>`<div class="score-chip"><strong>${s.home} – ${s.away}</strong><span>${pct(s.probability)}</span></div>`).join('')}</div><div class="mini-stats"><div><b>${pct(p.over25)}</b><span>2,5 GOL ÜSTÜ</span></div><div><b>${pct(p.btts)}</b><span>KARŞILIKLI GOL</span></div><div><b>${pct(p.under25)}</b><span>2,5 GOL ALTI</span></div></div><p class="inline-note">En olası skorun ihtimali ${pct(top.probability)}. Diğer skorların toplam olasılığı ${pct(1-top.probability)}. Eğitim ve ayrılan test maçlarının sonuçları yukarıdaki öğrenme kaydında gösterilir.</p><button class="text-button" data-view="method">Hesaplamayı ve doğrulamayı incele →</button></section></div><div class="section-heading"><h2>Benzer hikâyeler, gerçek sonuçlar</h2><button class="text-button" data-view="similar">Tüm benzer maçlar ↗</button></div><div class="card" style="padding:0">${neighborTable(result.neighbors.slice(0,4))}</div>`;}
function form(){const t=bundle.target;$('#view-form').innerHTML=`<div class="section-heading"><h2>Son ${options.formCount} resmi maç</h2><span class="kicker">YENİDEN ESKİYE · LİG + KUPALAR</span></div><div class="form-grid">${[['home',result.homeForm],['away',result.awayForm]].map(([side,rows])=>`<section class="card form-card"><h2>${esc(t[side].name)} <span class="muted small-text">· ${result.profiles[side].goalsFor} atılan / ${result.profiles[side].goalsAgainst} yenilen</span></h2>${rows.map(r=>`<div class="match-line"><span class="date">${date(r.date)}</span><button data-match="${r.id}">${esc(short(r.opponent.name))} <span class="venue">${r.venue==='home'?'EV':'DEP'}</span></button><b>${r.gf} – ${r.ga}</b><span class="form-pill ${r.result}">${({W:'G',D:'B',L:'M'})[r.result]}</span></div>`).join('')}<p class="inline-note">Skorlar takım perspektifindedir. Maça tıklayarak tüm istatistikleri açın.</p></section>`).join('')}</div><div class="section-heading"><h2>Tüm maç istatistikleri</h2><span class="kicker">EKSİK DEĞERLER ORTALAMAYA KATILMAZ</span></div><div class="controls"><div class="control"><label for="period">Maç bölümü</label><select id="period"><option value="All">Maçın tamamı</option><option value="FirstHalf">İlk yarı</option><option value="SecondHalf">İkinci yarı</option></select></div><div class="control"><label for="stat-search">İstatistik ara</label><input class="filter-input" id="stat-search" placeholder="xG, şut, pas, korner…" value="${esc(search)}"></div><button class="button ghost" id="stats-csv">CSV indir ↓</button></div><div id="all-stats"></div>`;$('#period').value=statPeriod;statTables();$('#period').onchange=e=>{statPeriod=e.target.value;statTables();};$('#stat-search').oninput=e=>{search=e.target.value;statTables();};$('#stats-csv').onclick=statsCsv;}
function statAverage(rows,key,against=false){const values=rows.map(r=>{const side=r.venue==='home'?0:1;return r.match.periods?.[statPeriod]?.[key]?.values?.[against?1-side:side];}).filter(Number.isFinite);return {mean:values.length?values.reduce((a,b)=>a+b,0)/values.length:null,n:values.length};}
function groupedStats(){const groups=new Map();for(const entry of bundle.inventory){if(search&&!`${entry.title} ${translation[entry.key]||''} ${entry.key}`.toLocaleLowerCase('tr').includes(search.toLocaleLowerCase('tr')))continue;if(!groups.has(entry.group))groups.set(entry.group,[]);groups.get(entry.group).push(entry);}return groups;}
function statTables(){const groups=groupedStats();$('#all-stats').innerHTML=[...groups].map(([group,entries])=>`<details class="stat-group" open><summary>${esc(groupNames[group]||group)} · ${entries.length} metrik</summary><div class="table-wrap"><table><thead><tr><th>İSTATİSTİK</th><th>${esc(short(bundle.target.home.name))}</th><th>RAKİPLERİ</th><th>${esc(short(bundle.target.away.name))}</th><th>RAKİPLERİ</th></tr></thead><tbody>${entries.map(s=>`<tr><td>${esc(translation[s.key]||s.title)}<small>${esc(s.key)}</small></td>${[[result.homeForm,false],[result.homeForm,true],[result.awayForm,false],[result.awayForm,true]].map(([rows,against])=>{const a=statAverage(rows,s.key,against);return `<td class="numeric">${number(a.mean,2)}<small>${a.n}/${rows.length} maç</small></td>`;}).join('')}</tr>`).join('')}</tbody></table></div></details>`).join('')||'<p class="empty">Bu aramada istatistik bulunamadı.</p>';}
function statsCsv(){const lines=[['Metrik','Takim','Mac','Tarih','Bolum','Kendi','Rakip']];for(const [team,rows]of [[bundle.target.home,result.homeForm],[bundle.target.away,result.awayForm]])for(const r of rows)for(const [key,s]of Object.entries(r.match.periods?.[statPeriod]||{})){const side=r.venue==='home'?0:1;lines.push([translation[key]||s.title,team.name,r.id,r.date,statPeriod,s.display?.[side]??'',s.display?.[1-side]??'']);}download('mathgoal-son'+options.formCount+'-istatistik.csv','\uFEFF'+lines.map(row=>row.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(';')).join('\r\n'),'text/csv;charset=utf-8');}
function graphSvg(mini=false){const nodes=result.graph.nodes,edges=result.graph.edges;const width=mini?520:1000,height=mini?255:540,cx=width/2,cy=height/2;const coords=new Map();const roots=nodes.filter(n=>n.root);roots.forEach((n,i)=>coords.set(String(n.id),{x:cx+(i===0?-1:1)*(mini?62:110),y:cy,color:i===0?'#c3ef79':'#e7ab80',root:true}));for(let d=1;d<=options.depth;d++){const ring=nodes.filter(n=>n.depth===d);ring.forEach((n,i)=>{const angle=2*Math.PI*i/Math.max(ring.length,1)-Math.PI/2;coords.set(String(n.id),{x:cx+Math.cos(angle)*(mini?(d===1?145:225):(d===1?230:435)),y:cy+Math.sin(angle)*(mini?(d===1?72:105):(d===1?145:230)),color:d===1?'#7c9b7c':'#506855',root:false});});}const lines=edges.map(e=>{const a=coords.get(String(e.source)),b=coords.get(String(e.target));if(!a||!b)return '';return `<line x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" stroke="${a.root?a.color:b.root?b.color:'#4d6b52'}" stroke-opacity="${(a.root||b.root)?0.32:0.18}" stroke-width="${mini?.7:1}"/>`;}).join('');return `<svg viewBox="0 0 ${width} ${height}" role="${mini?'img':'group'}" aria-label="${nodes.length} takım ve ${edges.length} bağlantıdan oluşan rakip ağı"><ellipse cx="${cx}" cy="${cy}" rx="${mini?145:230}" ry="${mini?72:145}" fill="none" stroke="#344936" stroke-dasharray="3 6"/><ellipse cx="${cx}" cy="${cy}" rx="${mini?225:435}" ry="${mini?105:230}" fill="none" stroke="#293a2c" stroke-dasharray="3 6"/>${lines}${nodes.map(n=>{const p=coords.get(String(n.id));if(!p)return '';const rr=p.root?(mini?22:28):(mini?3.5:6);return `<g class="graph-node graph-focus" ${mini?'':`data-node="${n.id}" tabindex="0" role="button" aria-label="${esc(n.name)} maçlarını göster"`}><title>${esc(n.name)} · Katman ${n.depth}</title>${p.root?`<circle cx="${p.x}" cy="${p.y}" r="${rr+7}" fill="${p.color}" opacity=".06"/>`:''}<circle cx="${p.x}" cy="${p.y}" r="${rr}" fill="${p.root?'#253522':p.color}" stroke="${p.color}" stroke-width="${p.root?1.3:.4}"/>${p.root?`<text x="${p.x}" y="${p.y+4}" text-anchor="middle" fill="${p.color}" font-size="${mini?11:13}" font-family="Manrope" font-weight="700">${({10260:'MUN',8678:'BOU'})[n.id]||short(n.name).replace(/[^A-Za-z]/g,'').slice(0,3).toUpperCase()}</text>`:''}${((!mini&&(nodes.length<=70||n.depth<=1))||(mini&&n.depth===1))?`<text class="graph-label" x="${p.x}" y="${p.y+(p.root?rr+18:-11)}" text-anchor="middle" fill="${p.root?p.color:'#8fa895'}" font-size="${mini?7.5:10}" font-family="DM Sans">${esc(short(n.name))}</text>`:''}</g>`;}).join('')}</svg>`;}
function controlsHtml(){return `<div class="controls"><div class="control"><label for="depth">Ağ derinliği</label><select id="depth"><option value="1">1 katman · Doğrudan rakipler</option><option value="2">2 katman · Rakiplerin rakipleri</option></select></div><div class="control"><label for="half-life">Zaman ağırlığı</label><select id="half-life"><option value="30">30 gün yarı ömür</option><option value="60">60 gün yarı ömür</option><option value="120">120 gün yarı ömür</option></select></div><div class="control"><label for="similarity-weight">Benzer maç etkisi <output>${pct(options.similarityWeight,0)}</output></label><input id="similarity-weight" type="range" min="0" max="40" step="5" value="${options.similarityWeight*100}"></div></div>`;}
function bindControls(){const d=$('#depth'),h=$('#half-life'),s=$('#similarity-weight');if(!d)return;d.value=options.depth;h.value=options.halfLife;d.onchange=()=>{options.depth=Number(d.value);testRun=null;recalc();};h.onchange=()=>{options.halfLife=Number(h.value);testRun=null;recalc();};s.onchange=()=>{options.similarityWeight=Number(s.value)/100;testRun=null;recalc();};s.oninput=()=>s.previousElementSibling.querySelector('output').textContent=pct(Number(s.value)/100,0);}
function network(){const g=result.graph;$('#view-network').innerHTML=`<div class="section-heading"><h2>Rakibinin rakibi ne söylüyor?</h2><span class="tag">${g.nodes.length} TAKIM · ${g.matchIds.length} TEKİL MAÇ</span></div><p class="section-desc">İki takımın son ${options.formCount} rakibiyle başlar. İkinci katmanda bu rakiplerin son ${options.formCount} maçına açılır. Her maç bir kez sayılır; rakiplerin hücum ve savunma gücü, bağlantılar boyunca 28 kez güncellenir.</p>${controlsHtml()}<div class="network-large">${graphSvg()}</div><p class="network-hint">Takım düğümlerine tıklayın veya klavye ile seçin. Dış katmandaki takımların geçmişi daha sınırlı olabilir.</p><div class="network-legend"><span><i></i>Ev sahibi</span><span><i></i>Deplasman</span><span><i></i>Bağlı takımlar</span></div><div class="network-info" id="node-info"><h3>Bir bağlantıyı inceleyin</h3><span class="small-text muted">Takımın son maçlarını ve ağdaki güç katsayılarını burada görün.</span></div>`;bindControls();$$('[data-node]').forEach(el=>{el.onclick=()=>nodeDetail(el.dataset.node);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();nodeDetail(el.dataset.node);}};});}
function nodeDetail(id){const n=result.graph.nodes.find(n=>String(n.id)===id),r=result.network.ratings[id],rows=history(bundle.matches,id,bundle.analysisAt??bundle.target.date,options.formCount,bundle.target.id);$('#node-info').innerHTML=`<h3>${esc(n.name)} <span class="tag">KATMAN ${n.depth}</span></h3><p class="inline-note">Hücum: ${number(r?.attack,2)} · Gol yeme: ${number(r?.defense,2)} · Ağda ${r?.games??0} maç. Katsayı 1 ortalamadır; yüksek gol yeme katsayısı daha zayıf savunma anlamına gelir.</p>${rows.length?rows.map(m=>`<div class="match-line"><span class="date">${date(m.date)}</span><button data-match="${m.id}">${esc(m.opponent.name)} <span class="venue">${m.venue==='home'?'EV':'DEP'}</span></button><b>${m.gf} – ${m.ga}</b><span class="form-pill ${m.result}">${({W:'G',D:'B',L:'M'})[m.result]}</span></div>`).join(''):'<p class="small-text muted">Bu veri kümesinde bu takımın geçmiş maçı yok.</p>'}`;const ps=result.playerAnalysis?.teams?.[String(id)]?.players||[];if(ps.length)$('#node-info').insertAdjacentHTML('beforeend',`<h3 class="spaced">Bu takımdaki oyuncular</h3><div class="pill-row">${ps.slice(0,12).map(p=>`<button class="select-pill" data-player-open="${p.playerId??p.id}" data-player-team="${id}">${esc(p.name)}</button>`).join('')}</div>`);}
function neighborTable(rows){if(!rows.length)return '<p class="empty">Yeterli geçmişi ve özellik örtüşmesi olan benzer maç bulunamadı.</p>';return `<div class="table-wrap"><table><thead><tr><th>TARİH</th><th>GEÇMİŞ KARŞILAŞMA</th><th>SONUÇ</th><th>PROFİL BENZERLİĞİ</th><th>VERİ ÖRTÜŞMESİ</th><th></th></tr></thead><tbody>${rows.map(n=>`<tr><td>${date(n.date)}</td><td>${esc(short(n.home.name))}<span class="muted"> – </span>${esc(short(n.away.name))}<small>Maç öncesi ${n.homeHistoryCount} / ${n.awayHistoryCount} maçlık geçmiş</small></td><td><strong>${n.score}</strong></td><td>${pct(n.similarity)}<div class="similarity-track"><span style="width:${n.similarity*100}%"></span></div></td><td>${n.featureCount}/24 özellik<small>${n.exact?'Birebir eşleşme':'Yakın profil · birebir değil'}</small></td><td><button data-neighbor="${n.id}">İncele ↗</button></td></tr>`).join('')}</tbody></table></div>`;}
function similar(){const p=result.prediction;$('#view-similar').innerHTML=`<div class="section-heading"><h2>Aynı profile yakın maçlar nasıl bitti?</h2><span class="tag">${result.neighbors.filter(n=>n.exact).length} BİREBİR EŞLEŞME</span></div><p class="section-desc">Karşılaştırma, her tarihsel maçın <strong>başlamadan önceki</strong> son ${options.formCount} maç profilini kullanır. Atılan ve yenilen gol, xG, şutlar, topa sahip olma, korner ve diğer ölçümler standart ölçeklerde karşılaştırılır. Benzerlik yüzdesi maç sonucunun gerçekleşme olasılığı değildir.</p><div class="callout">${result.neighbors.length} yakın profil bulundu. Tahmindeki gerçek benzer maç ağırlığı: <strong>${pct(p?.similarityWeight)}</strong>. Etki, etkin örneklem büyüklüğüne göre küçültülür (${number(p?.effectiveNeighbors)} maç). Birebir eşleşme yoksa yakın maçlar açıkça ayrı gösterilir.</div><div class="card" style="padding:0">${neighborTable(result.neighbors)}</div>`;}
function library(){const detailed=bundle.matches.filter(m=>Object.keys(m.stats).length).length;$('#view-data').innerHTML=`<div class="section-heading"><h2>Verinin kaynağı belli.</h2><span class="tag">FOTMOB · JSON ARŞİVİ</span></div><p class="section-desc">${date(bundle.collectedAt,true)} tarihinde FotMob’dan alınan veri görüntüsü. Maç istatistikleri, ilk/ikinci yarılar ve kaynak cevapları saklanır. Güncel kadro ve sezon bilgileri geçmiş tarihli oldukları doğrulanmadığından tahmine katılmaz.</p><div class="metric-strip"><div><b>${bundle.matches.length}</b><span>İndirilen maç</span></div><div><b>${detailed}</b><span>Ayrıntılı istatistiği bulunan</span></div><div><b>${Object.keys(bundle.teams).length}</b><span>Maçlarda görülen takım</span></div><div><b>${bundle.provenance.errors.length}</b><span>Veri toplama hatası</span></div></div><div class="grid two"><section class="card"><h2>Ham veriyi yanına al</h2><p class="small-text">Normalize edilmiş arşiv tüm maç ölçümlerini ve devrelerini içerir. Maç ayrıntılarındaki ham cevaplar şut haritası, oyuncu istatistikleri, kadro, olaylar ve diğer mevcut FotMob alanlarını da korur.</p><div class="data-actions"><button class="button primary" id="download-bundle">Maç arşivi JSON ↓</button><button class="button ghost" id="download-manifest">Kaynak listesi ↓</button></div><div class="data-actions"><button class="button ghost" data-snapshot="${bundle.target.home.id}">${esc(short(bundle.target.home.name))} takım verisi</button><button class="button ghost" data-snapshot="${bundle.target.away.id}">${esc(short(bundle.target.away.name))} takım verisi</button></div><p class="inline-note">Takım görüntüleri: kadro, oyuncu/sezon istatistikleri, transferler ve geçmiş alanları; kaynağın sunduğu kapsamla sınırlıdır. Sakatlık ve kadro verisi tahmine eklenmez.</p></section><section class="card"><h2>Toplama sınırları</h2><dl class="source-facts"><dt>Hedef maç</dt><dd>${esc(bundle.target.id)}</dd><dt>Veri zamanı</dt><dd>${esc(new Date(bundle.analysisAt??bundle.collectedAt).toLocaleString('tr-TR',{timeZone:'Europe/Istanbul'}))} İstanbul</dd><dt>Başlama</dt><dd>${esc(new Date(bundle.target.date).toLocaleString('tr-TR',{timeZone:'Europe/Istanbul'}))} İstanbul</dd><dt>Ağ</dt><dd>2 katman · Her düğümde son ${options.formCount} resmi maç</dd><dt>Karşılaştırma</dt><dd>Keşfedilen takımlarda 15–20 maç ve mevcut lig sezonu</dd><dt>Model verisi</dt><dd>${result.coverage?.matchCount??'—'} maç; bitişi bilinmeyene 3 saat tamamlanma payı</dd><dt>Gözlem</dt><dd>REA ev_c209138c…ffaa0 · Tarayıcı olay kaydı kısmi</dd><dt>Tazelik</dt><dd>Canlı akış değildir; Maçı analiz et düğmesiyle güncellenir.</dd></dl></section></div><div class="section-heading"><h2>Arşivdeki karşılaşmalar</h2><span class="kicker">${bundle.matches.length} MAÇ</span></div><div class="data-search"><label class="small-text" for="archive-search">Takım veya lig ara</label><input id="archive-search" class="filter-input" placeholder="Örn. Manchester, Milan, Premier League"></div><div class="card" style="padding:0" id="archive-table"></div>`;archiveTable('');$('#archive-search').oninput=e=>archiveTable(e.target.value);$('#download-bundle').onclick=()=>download('mathgoal-fotmob-archive.json',bundle);$('#download-manifest').onclick=()=>download('mathgoal-sources.json',bundle.provenance);}
function archiveTable(query){const rows=bundle.matches.filter(m=>`${m.home.name} ${m.away.name} ${m.leagueName}`.toLowerCase().includes(query.toLowerCase())).slice().reverse();$('#archive-table').innerHTML=`<div class="table-wrap"><table><thead><tr><th>TARİH</th><th>MAÇ</th><th>SKOR</th><th>LİG</th><th>KAPSAM</th></tr></thead><tbody>${rows.slice(0,120).map(m=>`<tr><td>${date(m.date)}</td><td><button data-match="${m.id}">${esc(short(m.home.name))} – ${esc(short(m.away.name))}</button></td><td>${m.homeScore} – ${m.awayScore}</td><td>${esc(m.leagueName)}</td><td>${Object.keys(m.stats).length} metrik</td></tr>`).join('')}</tbody></table></div><p class="inline-note" style="padding:0 14px">${rows.length} sonuç. İlk 120 satır gösterilir; tüm kayıtlar JSON arşivindedir.</p>`;}
function resultComparison(p){return renderResultComparison(bundle,p,{escapeHtml:esc,formatPercent:pct,formCount:options.formCount});}
function method(){const p=result.prediction;$('#view-method').innerHTML=`<div class="section-heading"><h2>Bir skorun nasıl hesaplandığını görün.</h2><span class="tag">AÇIKLANABİLİR MODEL</span></div><div class="grid two"><section class="card"><h2>Modelin adımları</h2>${[['Zaman kapısı','Hedef maç, gelecekteki ve tamamlanmamış maçlar dışarıda tutulur. Gerçek bitiş saati bilinmiyorsa başlama saatine 3 saat eklenerek muhafazakâr veri kullanılabilirliği sınırı uygulanır.'],['Son '+options.formCount+' maç profili','Her takımın son '+options.formCount+' resmi maçından hücum ve savunma ortalamaları çıkarılır. Eksik ölçümler sıfır sayılmaz; payda, ölçüm bulunan maç sayısıdır.'],['Rakiplerin rakipleri','Hücum ve gol yeme katsayıları ağ boyunca 28 iterasyonla güncellenir. 5 ortalama maçlık öncül ve zaman ağırlığı küçük örneklemin etkisini sınırlar.'],['Geçmişteki benzer profiller','Ev/deplasman yönü korunarak 24 özellik karşılaştırılır. Her tarihsel maç için yalnızca o maçtan önceki bilgiler kullanılır. En az 3 maçlık geçmiş ve %50 özellik örtüşmesi gerekir.'],['Skor dağılımı','%75 ağ ve %25 kısa form ile Poisson gol yoğunluğu çıkarılır; benzer maç skorlarının ampirik dağılımıyla kontrollü biçimde birleştirilir. Sonuçlardan öğrenilen düzeltme ve seçilen gol dağılımı uygulanır; ayrılan test maçları öğrenme kaydında raporlanır.']].map(([h,b],i)=>`<div class="method-step"><span>0${i+1}</span><div><h3>${h}</h3><p>${b}</p></div></div>`).join('')}</section><section class="card"><div class="card-title"><h2>Skor olasılık haritası</h2><span class="kicker">EV / DEPLASMAN</span></div>${p?heatmap(p):'<p class="empty">Yeterli geçmiş yok.</p>'}<p class="inline-note">Satırlar ev sahibi golleri, sütunlar deplasman golleri. Burada 0–5 gol gösterilir; model seçilen dağılıma göre 0–${p?.scoreGridMaximum??8} golü hesaplar. Poisson kuyruğunda dışarıda kalan kütle ${pct(p?.tailMass,3)}.</p><div class="callout">Beklenen gol: ${number(p?.homeXg,2)} – ${number(p?.awayXg,2)}<br>Poisson yoğunlukları: ${number(p?.poissonMeans?.home,2)} – ${number(p?.poissonMeans?.away,2)}<br>Benzer maçların nihai etkisi: ${pct(p?.similarityWeight)}<br>Ağ eğitiminde ${result.network.matchCount} tekil maç.</div><h2>Geçmişte ne kadar iyi çalışıyor?</h2><p class="small-text">Son 60 uygun maçta ileri yürüyen test. Her tahmin için arşiv o maçın öncesinde kesilir. Bu, tek döneme ve keşfedilen ağ örneklemine ait iç kontroldür; bağımsız test veya bahis getirisi ölçümü değildir. Bu ek test önceki takım tabanına aittir. Eğitilen modelin ayrı test sonucu Genel bakıştaki öğrenme kaydındadır. Oyuncu/H2H katmanları ve kadro değişiklikleri bu testte doğrulanmaz.</p><button class="button primary" id="run-backtest">Geçmiş testi çalıştır ↗</button><div id="backtest-results" class="backtest-results" role="status">${testRun?backtestHtml(testRun):''}</div></section></div>${resultComparison(p)}`;$('#run-backtest').onclick=runBacktest;}
function heatmap(p){const max=Math.max(...p.heatmap.map(c=>c.probability));let html='<div class="heatmap"><span></span>'+Array.from({length:6},(_,i)=>`<span class="axis">${i}</span>`).join('');for(let h=0;h<=5;h++){html+=`<span class="axis">${h}</span>`;for(let a=0;a<=5;a++){const c=p.heatmap.find(c=>c.home===h&&c.away===a);html+=`<span class="cell" title="${h}–${a}: ${pct(c.probability,2)}" style="background:rgba(160,208,98,${.05+.65*c.probability/max})">${number(c.probability*100)}%</span>`;}}return html+'</div>';}
function backtestHtml(test){const s=test.summary;if(!s?.sampleSize)return '<p class="inline-note">Test için yeterli geçmişe sahip maç yok.</p>';return `<div class="mini-stats"><div><b>${s.sampleSize}</b><span>TEST MAÇI</span></div><div><b>${pct(s.accuracy)}</b><span>1X2 DOĞRULUĞU</span></div><div><b>${pct(s.exactScoreAccuracy)}</b><span>TAM SKOR İSABETİ</span></div></div><p class="inline-note">Log kaybı: ${number(s.logLoss,3)} / eşit olasılık referansı: ${number(s.baselineLogLoss,3)}<br>Brier: ${number(s.brier,3)} / referans: ${number(s.baselineBrier,3)}<br>Bu iki kayıpta düşük değer daha iyidir.<br>${date(s.firstDate)} – ${date(s.lastDate)} · Aynı kaynak seçiminin iç testi; bağımsız doğrulama yok.</p>`;}
async function runBacktest(){const button=$('#run-backtest');button.disabled=true;$('#backtest-results').textContent='Her maçın öncesine dönülerek hesaplanıyor…';const worker=new Worker('/worker.mjs?v=2026-10-31.2',{type:'module'});worker.postMessage({bundle,options});worker.onmessage=e=>{button.disabled=false;if(e.data.error){$('#backtest-results').textContent=e.data.error;}else{testRun=e.data;$('#backtest-results').innerHTML=backtestHtml(testRun);}worker.terminate();};worker.onerror=()=>{button.disabled=false;$('#backtest-results').textContent='Test çalıştırılamadı.';worker.terminate();};}
function render(){heading();overview();const learningReport=trainingHtml(bundle,result,{esc,number,pct,date})+piPanelHtml(bundle,result,{esc,number})+marketSummaryHtml(result.marketAnalysis,bundle.target,{esc,pct}),learningAnchor=$('#view-overview .metric-strip');if(learningAnchor)learningAnchor.insertAdjacentHTML('afterend',learningReport);else $('#view-overview').insertAdjacentHTML('beforeend',learningReport);$('#view-markets').innerHTML=marketHtml(result.marketAnalysis,{esc,number,pct})||'<p class="empty">Seri analizi için yeterli geçmiş maç yok.</p>';bindMarketPanels($('#view-markets'),result.marketAnalysis,result.prediction?.heatmap,{pct});form();similar();library();method();if(active==='network')network();go(active);}
function openDialog(title,html){$('#detail-title').textContent=title;$('#detail-body').innerHTML=html;$('#detail-dialog').showModal();}
function findArchivedMatch(id){const key=String(id),match=bundle.matches.find(m=>String(m.id)===key)??bundle.playerHistoryMatches?.find(m=>String(m.id)===key);if(match)return match;for(const h of Object.values(bundle.playerHistories??{})){const row=h.matches?.find(m=>String(m.id)===key);if(row)return row;}return null;}
function matchDetail(id){const m=findArchivedMatch(id);if(!m)return;openDialog(`${m.home.name} ${m.homeScore} – ${m.awayScore} ${m.away.name}`,`<p class="inline-note">${date(m.date,true)} · ${esc(m.leagueName??'')} · ${m.stats?'Maç sonrası gözlemler':'Maç özeti; ayrıntılı istatistik bu arşivde eksik'}</p><div class="data-actions"><a class="button ghost" href="${esc(m.url)}" target="_blank" rel="noreferrer">FotMob ↗</a><button class="button ghost" data-raw="${m.id}">Tüm ham veriyi incele</button><button class="button ghost" data-normalized="${m.id}">Maç JSON indir ↓</button></div><div class="json-summary">${Object.entries(m.extras||{}).map(([k,v])=>`<span>${esc(k)}: ${v?'mevcut':'yok'}</span>`).join('')}</div>${Object.entries(m.periods||{All:m.stats??{}}).map(([period,stats])=>`<details class="stat-group" ${period==='All'?'open':''}><summary>${({All:'Maçın tamamı',FirstHalf:'İlk yarı',SecondHalf:'İkinci yarı'})[period]||esc(period)}</summary><div class="table-wrap"><table><thead><tr><th>İSTATİSTİK</th><th>${esc(short(m.home.name))}</th><th>${esc(short(m.away.name))}</th></tr></thead><tbody>${Object.entries(stats).map(([k,s])=>`<tr><td>${esc(translation[k]||s.title)}</td><td>${esc(s.display?.[0]??'—')}</td><td>${esc(s.display?.[1]??'—')}</td></tr>`).join('')}</tbody></table></div></details>`).join('')}`);}
async function rawDetail(id){const body=$('#detail-body');body.innerHTML='<p class="muted">Ham FotMob cevabı yükleniyor…</p>';try{let r=await fetch(`/api/raw?id=${encodeURIComponent(id)}`);if(!r.ok)r=await fetch(`/data/details/${encodeURIComponent(id)}.json`);if(!r.ok)throw Error('Ham cevap bu kurulumda bulunamadı.');const raw=await r.json();const keys=Object.keys(raw.content||{});body.innerHTML=`<p class="inline-note">FotMob’un döndürdüğü tüm alanlar. Bu görünümdeki maç sonrası bilgiler benzerlik profilini hesaplamakta kullanılmaz.</p><button class="button primary" id="raw-download">Ham FotMob JSON indir ↓</button><div class="json-summary spaced">${keys.map(k=>`<span>${esc(k)}</span>`).join('')}</div><label class="small-text" for="raw-section">İncelenecek bölüm</label><select class="filter-input" id="raw-section">${['general','header',...keys.map(k=>'content.'+k)].map(k=>`<option>${esc(k)}</option>`).join('')}</select><pre id="raw-text"></pre>`;const show=()=>{const k=$('#raw-section').value;$('#raw-text').textContent=JSON.stringify(k.startsWith('content.')?raw.content[k.slice(8)]:raw[k],null,2);};$('#raw-section').onchange=show;$('#raw-download').onclick=()=>download('fotmob-match-'+id+'.json',raw);show();}catch(e){body.textContent=e.message;}}
function neighborDetail(id){const n=result.neighbors.find(n=>String(n.id)===id);if(!n)return;openDialog(`Benzer profil: ${n.home.name} – ${n.away.name}`,`<p class="section-desc">Gerçek sonuç ${n.score}. Benzerlik ${pct(n.similarity)}. Aşağıdaki değerler maçın kendi istatistikleri değildir; her takımın maçtan önceki geçmiş ortalamalarıdır.</p><div class="table-wrap"><table><thead><tr><th>TARAF</th><th>ÖZELLİK</th><th>HEDEF PROFİL</th><th>TARİHSEL PROFİL</th></tr></thead><tbody>${n.comparable.map(c=>`<tr><td>${c.side==='home'?'Ev sahibi':'Deplasman'}</td><td>${esc(avgRows.find(x=>x[0]===c.metric)?.[1]||({shotsAgainst:'Rakip şut',points:'Puan',touchesBox:'Ceza sahası dokunuşu',bigChances:'Büyük fırsat'})[c.metric]||c.metric)}</td><td>${number(c.target,2)}</td><td>${number(c.historical,2)}</td></tr>`).join('')}</tbody></table></div>`);}
document.addEventListener('click',e=>{const view=e.target.closest('[data-view]');if(view){e.preventDefault();go(view.dataset.view);}const m=e.target.closest('[data-match]');if(m)matchDetail(m.dataset.match);const n=e.target.closest('[data-neighbor]');if(n)neighborDetail(n.dataset.neighbor);const raw=e.target.closest('[data-raw]');if(raw)rawDetail(raw.dataset.raw);const normalized=e.target.closest('[data-normalized]');if(normalized)download('match-'+normalized.dataset.normalized+'.json',findArchivedMatch(normalized.dataset.normalized));const snap=e.target.closest('[data-snapshot]');if(snap){const s=bundle.teamSnapshots[snap.dataset.snapshot];openDialog('Takım verisi · Güncel görüntü',`<p class="inline-note">${esc(s.warning)}</p><div class="data-actions"><button class="button primary" id="snapshot-download">Takım JSON indir ↓</button></div><pre>${esc(JSON.stringify(s,null,2))}</pre>`);$('#snapshot-download').onclick=()=>download('fotmob-team-'+snap.dataset.snapshot+'.json',s);}});
$('#form-count').onchange=e=>{options.formCount=Number(e.target.value)===5?5:10;try{localStorage.setItem('mathgoal-form-count',String(options.formCount));}catch{}testRun=null;recalc();};
try{options.formCount=localStorage.getItem('mathgoal-form-count')==='5'?5:10;}catch{}
$('#player-layer-toggle').onchange=e=>{options.playerLayer=e.target.checked;testRun=null;recalc();};
document.addEventListener('click',e=>{const p=e.target.closest('[data-player-open]');if(p){selectNetworkPlayer(p.dataset.playerOpen,p.dataset.playerTeam);go('players');}const match=e.target.closest('.player-match-node');if(match&&e.type==='keydown'&&e.key==='Enter')matchDetail(match.dataset.match);});
$('#prediction-model').onchange=e=>{options.playerGraphMode=e.target.value;const url=new URL(location.href);url.searchParams.set('model',e.target.value);window.history.replaceState(null,'',url);testRun=null;recalc();};
$('#h2h-layer-toggle').onchange=e=>{options.h2hLayer=e.target.checked;testRun=null;recalc();};
$('#close-dialog').onclick=()=>$('#detail-dialog').close();$('#detail-dialog').onclick=e=>{if(e.target===$('#detail-dialog'))$('#detail-dialog').close();};$('#export').onclick=()=>bundle&&download('mathgoal-analysis.json',{target:bundle.target,options,analysis:result,provenance:bundle.provenance});
window.addEventListener('hashchange',()=>{const h=location.hash.slice(1);if(titles[h]&&bundle&&h!==active)go(h);});
async function ensureCurrentVersion(pendingUrl=null){
 try{const r=await fetch('/api/health?t='+Date.now(),{cache:'no-store'});if(!r.ok)return true;const live=await r.json();if(live.uiVersion&&live.uiVersion!==APP_VERSION){if(pendingUrl)sessionStorage.setItem('mathgoal-pending-match',pendingUrl);location.reload();return false;}}catch{}return true;
}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')ensureCurrentVersion();});
window.addEventListener('pageshow',e=>{if(e.persisted)ensureCurrentVersion();});
$('#source-form').onsubmit=async e=>{e.preventDefault();if(!await ensureCurrentVersion($('#match-url').value))return;const requestedH2H=$('#match-url').value.includes(':tab=h2h');const id=parseMatchId($('#match-url').value);if(!id){toast('Geçerli bir FotMob maç bağlantısı veya maç kimliği girin.');return;}const button=$('#collect-button'),status=$('#collect-status');button.disabled=true;status.classList.remove('hidden','error');status.textContent='FotMob’dan veri toplanıyor. Rakip ağı birkaç dakika sürebilir…\n';try{const r=await fetch(`/api/collect?id=${encodeURIComponent(id)}`,{method:'POST'});if(!r.ok)throw Error(await r.text());const reader=r.body.getReader(),decoder=new TextDecoder();let log='';while(true){const {done,value}=await reader.read();if(done)break;log+=decoder.decode(value,{stream:true});status.textContent=log;status.scrollTop=status.scrollHeight;}if(!/Bitti: 0/.test(log))throw Error(log.includes('Önceki eğitim dosyası korunuyor')?'Yeni veri kaydedildi; eğitim güncellenemedi. Önceki eğitim sürümü korunuyor.':'Veri toplama tamamlanamadı. Mevcut analiz korunuyor.');trainingDataPromise=null;await load(id);if(requestedH2H)go('h2h');status.textContent='Yeni maç, pazar ağı ve geçmiş sonuçlarla güncellenen eğitim verisi yüklendi.';toast('Analiz güncellendi.');}catch(error){status.classList.add('error');status.textContent=error.message;}finally{button.disabled=false;}};
let trainingDataPromise;
function loadTrainingData(){return trainingDataPromise??=fetch('/data/training.json?v=2026-10-31.2',{cache:'no-cache'}).then(r=>r.ok?r.json():null).catch(()=>null);}
async function load(requestedId=new URLSearchParams(location.search).get('match')){
 const id=/^\d{4,12}$/.test(requestedId||'')?requestedId:null;
 let r=await fetch((id?'/data/matches/'+id+'.json':'/data/bundle.json')+'?t='+Date.now(),{cache:'no-store'});
 if(id&&!r.ok)throw Error('Bu maç henüz kaydedilmedi. FotMob bağlantısıyla Maçı analiz et düğmesini kullanın.');
 if(!r.ok)throw Error('Veri arşivi yüklenemedi.');
 bundle=await r.json();bundle.trainingData=await loadTrainingData();const requestedModel=new URLSearchParams(location.search).get('model');if(['auto','graph','baseline','gbdt','market-graph'].includes(requestedModel))options.playerGraphMode=requestedModel;if(id&&String(bundle.target.id)!==id)throw Error('Maç kimliği veri arşiviyle eşleşmiyor.');
 const url=new URL(location.href);url.searchParams.set('match',String(bundle.target.id));window.history.replaceState(null,'',url);
 $('#match-url').value=bundle.target.url;selectedTeam=String(bundle.target.home.id);active=titles[location.hash.slice(1)]?location.hash.slice(1):'overview';testRun=null;$('#loading').textContent='GBDT eğitiliyor; geçmiş maçlar doğrulanıyor…';if(await recalc()===false)return;$('#loading').classList.add('hidden');$('#app').classList.remove('hidden');
}
load().then(()=>{const pending=sessionStorage.getItem('mathgoal-pending-match');if(pending){sessionStorage.removeItem('mathgoal-pending-match');$('#match-url').value=pending;$('#source-form').requestSubmit();}}).catch(e=>{$('#loading').textContent=e.message;});
